<template><section class="min-w-0"><h2 class="section-title">Ближайшие занятия</h2><article v-for="b in upcoming" :key="b.id" class="card p-4 mt-3"><h3 class="font-bold">{{childById(b.childId)?.name}} · {{lessonById(b.lessonId)?.title}}</h3><p class="my-2 text-sm">{{formatDay(lessonById(b.lessonId)!.date)}} · {{lessonById(b.lessonId)?.time}} <span v-if="lessonById(b.lessonId)?.isMakeup" class="chip bg-honey-soft">Отработка</span></p><p class="text-xs text-forest">Записан</p><button class="btn-quiet mt-2" :disabled="busy" @click="openCancel(b.id)">Отменить запись</button><details class="mt-2"><summary class="text-xs cursor-pointer">Перенести занятие</summary><select v-model="target[b.id]" class="field mt-2"><option value="">Куда перенести</option><option v-for="l in targets(b.lessonId)" :key="l.id" :value="l.id">{{l.title}} · {{l.date}} {{l.time}}</option></select><button class="btn-quiet" :disabled="busy||!target[b.id]" @click="transfer(b.id)">Перенести</button></details></article><p v-if="!upcoming.length" class="card p-5 mt-3">Будущих записей нет. Выберите занятие в календаре.</p></section>
<BottomSheet :open="!!quote" title="Отмена записи" @close="quote=null"><template v-if="quote"><p v-if="!quote.allowed">Отмена сейчас недоступна по правилам мастерской. Свяжитесь с мастером.</p><template v-else><p v-if="quote.will_charge">Время бесплатной отмены закончилось. Запись будет отменена, однако занятие будет считаться использованным по правилам мастерской.</p><p v-else>Вы можете бесплатно отменить запись до {{deadline}}. При отмене занятие не будет списано с абонемента, а резерв освободится.</p><p class="mt-4">Вы уверены, что хотите отменить запись?</p><p v-if="changed" class="text-honey mt-2">Условия изменились. Проверьте их и подтвердите ещё раз.</p></template><div class="flex gap-2 mt-5"><button class="btn-ghost" @click="quote=null">{{quote.will_charge?'Вернуться':'Не отменять'}}</button><button v-if="quote.allowed" class="btn-primary" :disabled="busy" @click="cancel">Отменить запись</button></div></template></BottomSheet></template>
<script setup lang="ts">
import {computed,reactive,ref} from 'vue';import BottomSheet from './BottomSheet.vue';import {api,key} from '../shared/api';import {useDemo,refresh} from '../shared/use-demo';import {formatDay} from '../shared/demo';const {state,childById,lessonById}=useDemo();const target=reactive<Record<string,string>>({}),busy=ref(false),quote=ref<any>(null),changed=ref(false);const upcoming=computed(()=>state.bookings.filter(b=>b.status==='confirmed'&&future(b.lessonId)).sort((a,b)=>stamp(a.lessonId)-stamp(b.lessonId)));function stamp(id:string){const l=lessonById(id);return l?Date.parse(l.date+'T'+l.time+':00+05:00'):0}function future(id:string){return stamp(id)>Date.now()}function targets(id:string){return state.lessons.filter(l=>l.id!==id&&l.groupId===lessonById(id)?.groupId&&future(l.id))}const deadline=computed(()=>new Date(quote.value.free_cancel_until).toLocaleString('ru-RU',{timeZone:'Asia/Yekaterinburg',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}));async function openCancel(id:string){busy.value=true;try{quote.value=await api('/bookings/'+id+'/cancellation');changed.value=false;}finally{busy.value=false;}}async function cancel(){busy.value=true;try{const q=await api('/bookings/'+quote.value.booking_id+'/cancellation');if(q.allowed!==quote.value.allowed||q.will_charge!==quote.value.will_charge||q.free_cancel_until!==quote.value.free_cancel_until){quote.value=q;changed.value=true;return;}await api('/bookings/'+q.booking_id,'DELETE');quote.value=null;await refresh();}finally{busy.value=false;}}async function transfer(id:string){busy.value=true;try{await api('/bookings/'+id+'/transfer','POST',{target_lesson_id:target[id]},key());await refresh();}finally{busy.value=false;}}
</script>
